sysauto_script.script:
var certMetadataGr = new GlideRecord("sn_disco_certmgmt_certificate_metadata");
certMetadataGr.addQuery("auto_renewal_date>javascript:gs.endOfYesterday()^auto_renewal_date<=javascript:gs.endOfToday()");
certMetadataGr.addQuery("auto_renewal_state", "ready");
certMetadataGr.addQuery("auto_renew_enabled", "true");
certMetadataGr.query();
while(certMetadataGr.next()) {
	var result = new CertificateRenewalTaskUtil().triggerRenewal(certMetadataGr.certificate, certMetadataGr, null, 'scheduled_job');

	var retryCount = certMetadataGr.getValue('auto_renew_retry_count');
	var expectedError = gs.getMessage("Error while renewing certificate. Please try manually");
	var maxRetry = gs.getProperty('sn_disco_certmgmt.auto_renewal_max_retries', 0);

	if((!result['renewal_task_id'] || result['error'] == expectedError) &&  retryCount < maxRetry) {
		// reset auto_renewal_state and set the renewal date for the next day
		certMetadataGr.setValue('auto_renew_retry_count', parseInt(retryCount)+1);
		certMetadataGr.setValue('auto_renewal_state', 'ready');
		certMetadataGr.setValue('auto_renewal_date', gs.beginningOfTomorrow());
		certMetadataGr.update();
	}
}
